/*<include:placement_fixture>*/
partial class Harness {
 static void Main(){
 Test("all display modes x masks x categories x focus obey policy",()=>{for(int mode=0;mode<4;mode++)for(int mask=0;mask<32;mask++)for(int c=0;c<5;c++)foreach(bool focus in new[]{false,true}){bool expected=mode==0?false:mode==1?focus:mode==3||(mask&(1<<c))!=0;Check(PlacementCategoryVisible((PlacementDisplayMode)mode,mask,c,focus)==expected,"filter");}});
 Test("new users start hidden and do not write defaults",()=>{var h=new Harness();h.LoadPlacementDisplayPreferences();Check(h._placementDisplayMode==PlacementDisplayMode.Hidden&&!h._showPlacementMarkers&&!File.Exists(PlacementDisplayFile),"default");});
 Test("Hide All gates explicit auto preview and selected highlight",()=>{var h=new Harness{_autoLotPreview=true,_automaticLotMode=true,_menuPage=MenuPage.PointEditor};h._bays[0].IsSet=true;h._editingPoint=h._bays[0];h.DrawPlacementMarkers();Check(World.markers.Count==0&&GTA.Native.Function.lines==0&&h._autoLotPreview,"hide all");});
 Test("Focused draws only actual selected physical waypoint",()=>{var h=new Harness{_placementDisplayMode=PlacementDisplayMode.Focused,_menuPage=MenuPage.MechanicRoutePoints,_selection=2};h._serviceRoute[2].IsSet=h._serviceRoute[3].IsSet=h._customerDropoff.IsSet=true;h._serviceRoute[2].Position=new Vector3(2,0,0);h.DrawPlacementMarkers();Check(World.markers.Count==2&&World.markers.All(x=>x.X==2)&&GTA.Native.Function.lines==0,"focus clutter");});
 Test("Custom category visibility wins over selected-point highlighting",()=>{var h=new Harness{_placementDisplayMode=PlacementDisplayMode.Custom,_activeMarkerCategories=1,_menuPage=MenuPage.PointEditor};h._serviceRoute[0].IsSet=h._customerDropoff.IsSet=true;h._editingPoint=h._serviceRoute[0];h.DrawPlacementMarkers();Check(World.markers.Count==1,"custom override");});
 Test("Show All can inspect inactive custom walking coordinates",()=>{var h=new Harness{_placementDisplayMode=PlacementDisplayMode.All,_showMenu=false};h._serviceRoute[0].IsSet=h._arrivalRoute[1].IsSet=true;h.DrawPlacementMarkers();Check(World.markers.Count==2,"saved but inactive hidden");});
 Test("unset selected coordinates do not invent a marker",()=>{var h=new Harness{_placementDisplayMode=PlacementDisplayMode.Focused,_menuPage=MenuPage.PointEditor,_editingPoint=new WorkBay()};h.DrawPlacementMarkers();Check(World.markers.Count==0,"invented focus");});
 Test("preferences and remembered custom mask survive reload",()=>{var h=new Harness();Check(h.SetPlacementDisplay(PlacementDisplayMode.Custom,5,5),"save");var next=new Harness();next.LoadPlacementDisplayPreferences();Check(next._placementDisplayMode==PlacementDisplayMode.Custom&&next._activeMarkerCategories==5&&next._customMarkerCategories==5&&next._showPlacementMarkers,"reload");});
 Test("Hide All preserves last custom mask and preview toggle",()=>{var h=new Harness{_selection=1,_autoLotPreview=true};h.SetPlacementDisplay(PlacementDisplayMode.Custom,10,10);h.ExecuteMarkerSelection();Check(h._placementDisplayMode==PlacementDisplayMode.Hidden&&h._customMarkerCategories==10&&h._autoLotPreview,"custom lost");h._selection=3;h.ExecuteMarkerSelection();Check(h._placementDisplayMode==PlacementDisplayMode.Custom&&h._activeMarkerCategories==10,"restore custom");});
 Test("Show Current Category does not overwrite remembered custom",()=>{var h=new Harness{_markerFocusCategory=2,_selection=2};h.SetPlacementDisplay(PlacementDisplayMode.Custom,17,17);h.ExecuteMarkerSelection();Check(h._activeMarkerCategories==4&&h._customMarkerCategories==17,"custom overwritten");h._selection=3;h.ExecuteMarkerSelection();Check(h._activeMarkerCategories==17,"restore");});
 Test("category toggles are explicit and update custom selection",()=>{var h=new Harness{_selection=4};h.ExecuteMarkerSelection();Check(h._placementDisplayMode==PlacementDisplayMode.Custom&&h._activeMarkerCategories==30&&h._customMarkerCategories==30,"toggle");});
 Test("preference write failure retains previous visible state and file",()=>{var h=new Harness();h.SetPlacementDisplay(PlacementDisplayMode.Focused,3,3);byte[] old=File.ReadAllBytes(PlacementDisplayFile);ScriptSettings.Fail=true;Check(!h.SetPlacementDisplay(PlacementDisplayMode.All,31,31)&&h._placementDisplayMode==PlacementDisplayMode.Focused&&old.SequenceEqual(File.ReadAllBytes(PlacementDisplayFile)),"failed save mutated");});
 Test("future preferences fail closed and remain byte-identical",()=>{Directory.CreateDirectory(DataDirectory);File.WriteAllText(PlacementDisplayFile,"[Display]\nVersion=2\nMode=3\nUnknown=keep\n");var old=File.ReadAllBytes(PlacementDisplayFile);var h=new Harness();h.LoadPlacementDisplayPreferences();Check(!h.SetPlacementDisplay(PlacementDisplayMode.All,31,31)&&h._placementDisplayMode==PlacementDisplayMode.Hidden&&old.SequenceEqual(File.ReadAllBytes(PlacementDisplayFile)),"future rewritten");});
 Test("preference keys do not touch business Save or Settings",()=>{Directory.CreateDirectory(DataDirectory);File.WriteAllText(SaveFile,"cash=12\n");File.WriteAllText(SettingsFile,"unknown=keep\n");var h=new Harness();h.SetPlacementDisplay(PlacementDisplayMode.All,31,9);Check(File.ReadAllText(SaveFile)=="cash=12\n"&&File.ReadAllText(SettingsFile)=="unknown=keep\n","business touched");});
 Test("mask high bits are bounded on reload",()=>{Directory.CreateDirectory(DataDirectory);File.WriteAllText(PlacementDisplayFile,"[Display]\nVersion=1\nMode=99\nActiveMask=255\nCustomMask=64\n");var h=new Harness();h.LoadPlacementDisplayPreferences();Check(h._placementDisplayMode==PlacementDisplayMode.Hidden&&h._activeMarkerCategories==31&&h._customMarkerCategories==0,"mask bounds");});
 Test("world marker rendering performs no preference file IO",()=>{var h=new Harness{_placementDisplayMode=PlacementDisplayMode.All};h._bays[0].IsSet=true;for(int i=0;i<100;i++)h.DrawPlacementMarkers();Check(!Directory.Exists(DataDirectory),"render wrote disk");});
 Test("paused and far-away previews issue no draw natives",()=>{var h=new Harness{_placementDisplayMode=PlacementDisplayMode.All};h._customerDropoff.IsSet=true;Game.IsPaused=true;h.DrawPlacementMarkers();Game.IsPaused=false;Game.Player.Character.Position=new Vector3(1000,0,0);h.DrawPlacementMarkers();Check(World.markers.Count==0&&GTA.Native.Function.lines==0,"range/pause");});
 Test("parking outlines are cached until position or heading changes",()=>{var h=new Harness();var v=new PlacementVisual{Point=new WorkBay{IsSet=true},Shape=1};h.DrawPlacementVisual(v,Color.Teal);var outline=v.Outline;for(int i=0;i<100;i++)h.DrawPlacementVisual(v,Color.Teal);Check(ReferenceEquals(outline,v.Outline),"outline recalculated");v.Point.Heading=90;h.DrawPlacementVisual(v,Color.Teal);Check(!ReferenceEquals(outline,v.Outline),"stale heading");});
 Test("computed auto bay previews avoid repeated placement calculations",()=>{var h=new Harness{_autoLotPreview=true,_automaticLotMode=true,_placementDisplayMode=PlacementDisplayMode.All};h._bays[0].IsSet=true;for(int i=0;i<100;i++)h.DrawComputedBayPreviews(new Vector3(),null);Check(h.computed==1,"per-frame calculation");h._autoLotOffsetMeters=8;h.DrawComputedBayPreviews(new Vector3(),null);Check(h.computed==2,"offset cache");});
 Test("Custom service-bay switch also filters computed preview",()=>{var h=new Harness{_autoLotPreview=true,_automaticLotMode=true,_placementDisplayMode=PlacementDisplayMode.Custom,_activeMarkerCategories=1};h._bays[0].IsSet=true;h.DrawComputedBayPreviews(new Vector3(),null);Check(h.computed==0&&GTA.Native.Function.lines==0,"computed bypass");});
 Test("marker page retains exact physical context and caller",()=>{var h=new Harness{_menuPage=MenuPage.PointEditor};h._editingPoint=h._serviceRoute[3];h.OpenMarkerDisplay();Check(ReferenceEquals(h._markerFocusPoint,h._serviceRoute[3])&&h._markerFocusCategory==1&&h._placementMenuReturns[MenuPage.PlacementMarkers].Key==MenuPage.PointEditor,"context");});
 Test("registry point identities and save-section names are unique",()=>{var h=new Harness();var r=h.PlacementVisuals();Check(r.Count==58&&r.Select(x=>x.Point).Distinct().Count()==r.Count&&r.Select(x=>x.Section).Distinct().Count()==r.Count,"registry aliases");Check(!r.Any(x=>x.Section=="SupplierWarehousePickup"),"fixed warehouse editable");});
 Test("marker identity command never changes coordinates",()=>{var h=new Harness{_selection=10};h._markerFocusPoint=h._serviceRoute[1];h.ExecuteMarkerSelection();Check(h.notices.Single().Contains("ServiceWaypoint2")&&!h._serviceRoute[1].IsSet&&!Directory.Exists(DataDirectory),"identity side effect");});
 Test("nonfinite saved coordinates or directed heading never reach draw natives",()=>{var h=new Harness{_placementDisplayMode=PlacementDisplayMode.All,_showMenu=false};h._bays[0].IsSet=true;h._bays[0].Position=new Vector3(float.NaN,0,0);h._vehicleParkingBays[0].IsSet=true;h._vehicleParkingBays[0].Heading=float.NaN;h.DrawPlacementMarkers();Check(World.markers.Count==0&&GTA.Native.Function.lines==0,"invalid draw");});
 Console.WriteLine($"markers37 {passed}/{passed} PASS; real mode/registry/preferences/render-cache methods with synthetic files/native adapters; GTA NOT RUN");
 }
}
